import * as T from 'three';
import {mergeGeometries} from 'three/addons/utils/BufferGeometryUtils.js';
export function compactStaticGeometry(root,include=()=>true){const batches=new Map(),old=[];root.updateWorldMatrix(true,true);const inverse=new T.Matrix4().copy(root.matrixWorld).invert();root.traverse(n=>{if(!n.isMesh||!include(n))return;const geometry=n.geometry.index?n.geometry.toNonIndexed():n.geometry.clone();geometry.applyMatrix4(new T.Matrix4().copy(inverse).multiply(n.matrixWorld));const key=n.material.uuid+'|'+Object.keys(geometry.attributes).sort().join(',');if(!batches.has(key))batches.set(key,{material:n.material,parts:[]});batches.get(key).parts.push(geometry);old.push(n);});for(const n of old){n.removeFromParent();n.geometry.dispose();}for(const{material,parts}of batches.values()){const mesh=new T.Mesh(mergeGeometries(parts),material);mesh.castShadow=mesh.receiveShadow=true;mesh.name='harbor.parked.batch';root.add(mesh);parts.forEach(g=>g.dispose());}}
